import boto3
from datetime import datetime, timedelta

def compare_metric_values(
    resource_id_1,
    resource_id_2,
    metric_name,
    dimension_name='InstanceId',
    namespace='AWS/EC2',
    duration_minutes=60,
    statistic='Average'
):
    client = boto3.client('cloudwatch')
    end_time = datetime.utcnow()
    start_time = end_time - timedelta(minutes=duration_minutes)
    period = 300  # 5 minutes

    metric_queries = [
        {
            'Id': 'resource1',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': [
                        {
                            'Name': dimension_name,
                            'Value': resource_id_1
                        }
                    ]
                },
                'Period': period,
                'Stat': statistic,
                'Unit': 'Percent'
            }
        },
        {
            'Id': 'resource2',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': [
                        {
                            'Name': dimension_name,
                            'Value': resource_id_2
                        }
                    ]
                },
                'Period': period,
                'Stat': statistic,
                'Unit': 'Percent'
            }
        }
    ]

    response = client.get_metric_data(
        MetricDataQueries=metric_queries,
        StartTime=start_time,
        EndTime=end_time
    )

    results = {result['Id']: result for result in response['MetricDataResults']}

    def average_values(values):
        return sum(values) / len(values) if values else 0.0

    val1 = average_values(results['resource1']['Values'])
    val2 = average_values(results['resource2']['Values'])

    difference = val1 - val2
    ratio = val2 / val1 if val1 != 0 else 0

    return {
        'resource1_value': val1,
        'resource2_value': val2,
        'difference': difference,
        'ratio_resource2_over_resource1': ratio
    }
